/* @lc app=leetcode id=3013 lang=kotlin */ class Solution { fun bu(c: IntArray, s: LongArray, rk: Int, d: Int, v: Long) = generateSequence(rk) { it + (it and -it) }.takeWhile { it < c.size }.forEach { i -> c.set(i, c[i] + d).also { s[i] += d * v } } fun minimumCost(nums: IntArray, k: Int, dist: Int): Long = nums.size.let { n -> nums.toSet().sorted().let { vals -> IntArray(vals.size + 1).let { c -> LongArray(vals.size + 1).let { s -> (2..minOf(n - 1, 1 + dist)).forEach { bu(c, s, vals.binarySearch(nums[it]) + 1, 1, nums[it].toLong()) }.let { (1 until n).fold(Long.MAX_VALUE) { best, j -> (if (minOf(n - 1, j + dist) - j >= k - 2) minOf(best, nums[j] + generateSequence(Integer.highestOneBit(vals.size)) { it / 2 }.takeWhile { it >= 1 }.fold(Triple(0, k - 2, 0L)) { (pos, rem, tot), st -> if (pos + st <= vals.size && c[pos + st] <= rem) Triple(pos + st, rem - c[pos + st], tot + s[pos + st]) else Triple(pos, rem, tot) }.let { (pos, rem, tot) -> tot + rem.toLong() * (if (pos < vals.size) vals[pos] else 0) }) else best).also { if (j + 1 < n) bu(c, s, vals.binarySearch(nums[j + 1]) + 1, -1, nums[j + 1].toLong()) }.also { if (j + 1 + dist < n) bu(c, s, vals.binarySearch(nums[j + 1 + dist]) + 1, 1, nums[j + 1 + dist].toLong()) } }.let { it + nums[0] } } } } } } }